import test from 'node:test';
import assert from 'node:assert/strict';
import {validateFailedContext,requireSameFailedContext,validateRenewal} from './forward-guards.mjs';
const source='9bf924ff3389fd5f5a41c03d062a40c429216585',baseline='9541b1686d7941f89e564723271e48bf85a21a89',build='RZT3KRDc_BngwxXFhSv1S',digest='a'.repeat(64);
const grant={source,baseline,baselineBuildId:build,environmentSha256:digest,build:{lockSha256:digest,packageSha256:digest},installId:'2024815a-9960-4c16-8121-0f3cf1f727af',issuedAt:'2026-10-27T04:32:55.532Z',expiresAt:'2026-10-27T05:02:55.532Z'};
const fixture=()=>({kind:'FAILED_UNACTIVATED_STAGING_SNAPSHOT',status:{state:'failed',ref:source,phase:'ci-build-verify',exit_code:'1',pid:'3354827',stale_build:'1',built_ref:baseline,built_build_id:build,build_id:build,log:'/var/tmp/aihr-deploy/original.log'},current:{ref:source,result:'failed',phase:'ci-build-verify',pid:'3354827',log:'/var/tmp/aihr-deploy/original.log',exit_code:'1'},pendingPresent:false,pendingRef:null,originalGrantEqual:true,originalGrantSha256:digest,originalEntries:['authorization.json','packet','store.json'],absentOwnedOutputs:true,deployPidAlive:false,service:'active',servicePid:'3327801',healthStatus:200,environmentSha256:digest,lockMarker:digest,packageSha256:digest,lockSha256:digest,logContainsExactSharpFailure:true,currentSha256:digest,lastOkSha256:digest,oldLogSha256:digest,bootIdSha256:digest,oldDirectory:{device:'1',inode:'2'},activeDirectory:{device:'1',inode:'3'}});
test('actual failed context and real pending transition preserve original failure',()=>{const before=fixture();validateFailedContext(before,grant);const pending=structuredClone(before);pending.status.state='incomplete';pending.pendingPresent=true;pending.pendingRef=source;validateFailedContext(pending,grant,{announced:true});requireSameFailedContext(before,pending);});
for(const[name,change]of[
 ['invented ready state',r=>r.status.state='ok'],['phase advanced',r=>r.status.phase='migrate'],['changed source',r=>r.status.ref=baseline],['changed active build',r=>r.status.build_id='other'],['current result cleared',r=>r.current.result=''],['current process changed',r=>r.current.pid='7'],['failed process alive',r=>r.deployPidAlive=true],['service restarted',r=>r.servicePid='7'],['unhealthy old service',r=>r.healthStatus=503],['unexpected pending',r=>r.pendingPresent=true],['historical grant changed',r=>r.originalGrantEqual=false],['owned stage exists',r=>r.absentOwnedOutputs=false],['unknown old output',r=>r.originalEntries.push('next')],['environment moved',r=>r.environmentSha256='b'.repeat(64)],['dependency reinstall required',r=>r.lockMarker='b'.repeat(64)],['dependency package changed',r=>r.packageSha256='b'.repeat(64)],['failure not Sharp',r=>r.logContainsExactSharpFailure=false],
])test('refuses '+name,()=>{const r=fixture();change(r);assert.throws(()=>validateFailedContext(r,grant));});
test('pending marker cannot conceal a cleared underlying failure',()=>{const r=fixture();r.status.state='incomplete';r.pendingPresent=true;r.pendingRef=source;r.current.result='ok';assert.throws(()=>validateFailedContext(r,grant,{announced:true}));});
for(const key of ['currentSha256','lastOkSha256','oldLogSha256','bootIdSha256','oldDirectory','activeDirectory','servicePid'])test('refuses changed recovery anchor '+key,()=>{const before=fixture(),after=fixture();after[key]=typeof after[key]==='object'?{device:'1',inode:'99'}:'b'.repeat(64);assert.throws(()=>requireSameFailedContext(before,after));});
const fresh=()=>{const now=Date.now();return {...structuredClone(grant),installId:'9769c47a-d37e-4a11-b1d3-a5637da3856e',issuedAt:new Date(now).toISOString(),expiresAt:new Date(now+1800000).toISOString()};};
test('fresh distinct authority preserves original build and immutable historical grant',()=>{const old=JSON.stringify(grant),next=fresh();validateRenewal(grant,next);assert.equal(JSON.stringify(grant),old);});
for(const[name,change]of[['same UUID',r=>r.installId=grant.installId],['relabelled source',r=>r.source=baseline],['different environment',r=>r.environmentSha256='b'.repeat(64)],['altered build',r=>r.build.lockSha256='b'.repeat(64)],['expired',r=>r.expiresAt=new Date(Date.now()-1).toISOString()],['extended window',r=>r.expiresAt=new Date(Date.now()+3600000).toISOString()]])test('fresh authority refuses '+name,()=>{const r=fresh();change(r);assert.throws(()=>validateRenewal(grant,r));});
